    old={p:(p.read_bytes() if p.exists() else None) for p in (MOD,TEST,RUN,INIT)}
    try:
        write_exact(MOD,MODULE_SOURCE);write_exact(TEST,TEST_SOURCE);write_exact(RUN,RUN_SOURCE)
        update_init(INIT,"from .olf_004_feedback_aware_reasoning_runtime import *")
        subprocess.run([sys.executable,str(TEST)],cwd=str(ROOT),check=True)
        subprocess.run([sys.executable,str(RUN),"--check"],cwd=str(ROOT),check=True)
    except Exception:
        for p,b in old.items():restore(p,b)
        print("[ROLLBACK] OLF-004 failed; affected files restored");raise
